30	/**
31	 * AWS Encryption SDK를 사용한 데이터 암복호화 서비스.
32	 * <p>
33	 * AWS Encryption SDK의 Envelope Encryption + Data Key Caching을 활용하여
34	 * KMS API 호출을 최소화하면서 안전한 암복호화를 수행한다.
35	 * <p>
36	 * {@link AwsKmsConfig}에서 CMK별 Bean으로 등록된다:
37	 * <ul>
38	 *   <li>"locationEncryptionService" — CMK 1: 위치/트래픽 (ECGI, GPS)</li>
39	 *   <li>"dataEncryptionService" — CMK 2: 개인정보 (CTN, IMEI 등)</li>
40	 * </ul>
41	 * <p>
42	 * SDK가 내부적으로 처리하는 항목:
43	 * <ul>
44	 *   <li>Data Key 생성 (GenerateDataKey)</li>
45	 *   <li>AES-GCM 암호화/복호화</li>
46	 *   <li>IV 생성 및 관리</li>
47	 *   <li>Envelope 바이너리 포맷 (encrypted message)</li>
48	 *   <li>Encryption Context 바인딩</li>
49	 * </ul>
50	 */
51	public class AwsKmsEncryptionService {
52	
53	    private static final Logger logger = LoggerFactory.getLogger(AwsKmsEncryptionService.class);
54	
55	    /** Data Key 캐시 최대 항목 수 */
56	    private static final int CACHE_CAPACITY = 100;
57	    /** 캐시된 Data Key 최대 유효 시간 (분) */
58	    private static final int MAX_AGE_MINUTES = 5;
59	    /** 하나의 캐시된 Data Key로 암호화할 수 있는 최대 메시지 수 */
60	    private static final int MAX_MESSAGES_PER_KEY = 1000000;
61	
62	    private final AwsCrypto crypto;
63	    private final CachingCryptoMaterialsManager cachingCmm;
64	    private final MasterKeyProvider<KmsMasterKey> masterKeyProvider;
65	
66	    public AwsKmsEncryptionService(String keyArn, String region) {
67	        // 1. AwsCrypto 인스턴스 (RequireEncryptRequireDecrypt = 기본 커밋 정책)
68	        this.crypto = AwsCrypto.builder()
69	                .withCommitmentPolicy(CommitmentPolicy.RequireEncryptRequireDecrypt)
70	                .build();
71	
72	        // 2. KMS Master Key Provider (AWS SDK v2 기반)
73	        //    LocalStack 사용 시 endpoint override + dummy credential 설정
74	        KmsMasterKeyProvider.Builder providerBuilder = KmsMasterKeyProvider.builder()
75	                .defaultRegion(Region.of(region));
76	
77	        String localstackEndpoint = System.getProperty("LOCALSTACK_ENDPOINT");
78	        KmsClient kmsClient;
79	        if (localstackEndpoint != null && !localstackEndpoint.isBlank()) {
80	            logger.info("AwsKmsEncryptionService: Using LocalStack endpoint = {}", localstackEndpoint);
81	            kmsClient = KmsClient.builder()
82	                    .region(Region.of(region))
83	                    .endpointOverride(URI.create(localstackEndpoint))
84	                    .credentialsProvider(StaticCredentialsProvider.create(
85	                            AwsBasicCredentials.create("test", "test")))
86	                    .build();
87	            providerBuilder.customRegionalClientSupplier(r -> kmsClient);
88	        } else {
89	            kmsClient = KmsClient.builder()
90	                    .region(Region.of(region))
91	                    .build();
92	        }
93	
94	        // alias → ARN 변환 (환경 무관)
95	        // AWS Encryption SDK는 암호화 시 헤더에 항상 ARN을 기록하므로
96	        // buildStrict에도 ARN을 사용해야 복호화 시 key ID가 일치함
97	        if (keyArn.startsWith("alias/")) {
98	            String resolvedArn = kmsClient.describeKey(
99	                    software.amazon.awssdk.services.kms.model.DescribeKeyRequest.builder()
100	                            .keyId(keyArn).build()
101	            ).keyMetadata().arn();
102	            logger.info("AwsKmsEncryptionService: Resolved {} → {}", keyArn, resolvedArn);
103	            keyArn = resolvedArn;
104	        }
105	
106	        this.masterKeyProvider = providerBuilder.buildStrict(keyArn);
107	
108	        // 3. Data Key 캐싱 설정
109	        CryptoMaterialsCache cache = new LocalCryptoMaterialsCache(CACHE_CAPACITY);
110	        this.cachingCmm = CachingCryptoMaterialsManager.newBuilder()
111	                .withMasterKeyProvider(masterKeyProvider)
112	                .withCache(cache)
113	                .withMaxAge(MAX_AGE_MINUTES, TimeUnit.MINUTES)
114	                .withMessageUseLimit(MAX_MESSAGES_PER_KEY)
115	                .build();
116	    }
117	
118	    /**
119	     * AWS Encryption SDK로 데이터 암호화.
120	     * <p>
121	     * SDK가 내부적으로 Data Key 생성, AES-GCM 암호화, Envelope 포맷 생성을 모두 처리한다.
122	     * CachingCMM을 통해 Data Key가 캐싱되어 KMS API 호출이 최소화된다.
123	     *
124	     * @param plaintext 평문 데이터
125	     * @return Base64 인코딩된 encrypted message 또는 빈 문자열 (null/빈 입력 또는 실패 시)
126	     */
127	    @SuppressWarnings("deprecation") // SDK 3.x: CachingCMM은 MasterKeyProvider만 지원, keyring 미지원
128	    public String encrypt(String plaintext) {
129	        if (plaintext == null || plaintext.isEmpty()) {
130	            return "";
131	        }
132	        try {
133	            long start = System.nanoTime();
134	            Map<String, String> encryptionContext = Collections.emptyMap();
135	            CryptoResult<byte[], ?> result = crypto.encryptData(
136	                    cachingCmm,
137	                    plaintext.getBytes(StandardCharsets.UTF_8),
138	                    encryptionContext);
139	            long elapsed = (System.nanoTime() - start) / 1_000_000;
140	            logger.info("[encrypt] completed in {}ms", elapsed);
141	            return Base64.getEncoder().encodeToString(result.getResult());
142	        } catch (Exception e) {
143	            logger.error("AwsKmsEncryptionService - [encrypt] ERROR", e);
144	            throw new RuntimeException("ENCRYPTION_FAILED", e);
145	        }
146	    }
147	
148	    /**
149	     * AWS Encryption SDK로 데이터 복호화.
150	     *
151	     * @param ciphertext Base64 인코딩된 encrypted message
152	     * @return 복호화된 평문 또는 빈 문자열 (null/빈 입력 또는 실패 시)
153	     */
154	    @SuppressWarnings("deprecation") // SDK 3.x: strict mode MasterKeyProvider 사용
155	    public String decrypt(String ciphertext) {
156	        if (ciphertext == null || ciphertext.isEmpty()) {
157	            return "";
158	        }
159	        try {
160	            long start = System.nanoTime();
161	            byte[] encryptedBytes = Base64.getDecoder().decode(ciphertext);
162	            CryptoResult<byte[], ?> result = crypto.decryptData(
163	                    cachingCmm,
164	                    encryptedBytes);
165	            long elapsed = (System.nanoTime() - start) / 1_000_000;
166	            logger.info("[decrypt] completed in {}ms", elapsed);
167	            return new String(result.getResult(), StandardCharsets.UTF_8);
168	        } catch (Exception e) {
169	            logger.error("AwsKmsEncryptionService - [decrypt] ERROR", e);
170	            throw new RuntimeException("ENCRYPTION_FAILED", e);
171	        }
172	    }
173	
174	    /**
175	     * 배치 암호화.
176	     * <p>
177	     * CachingCMM이 Data Key를 자동으로 캐싱하므로 배치 내에서
178	     * KMS API 호출이 최소화된다.
179	     *
180	     * @param plaintextList 평문 리스트
181	     * @return 암호화된 데이터 리스트 또는 빈 리스트 (null/빈 입력 또는 실패 시)
182	     */
183	    public List<String> encryptBatch(List<String> plaintextList) {
184	        if (plaintextList == null || plaintextList.isEmpty()) {
185	            return Collections.emptyList();
186	        }
187	        try {
188	            List<String> results = new ArrayList<>(plaintextList.size());
189	            for (String plaintext : plaintextList) {
190	                results.add(encrypt(plaintext));
191	            }
192	            return results;
193	        } catch (Exception e) {
194	            logger.error("AwsKmsEncryptionService - [encryptBatch] ERROR", e);
195	            throw new RuntimeException("ENCRYPTION_FAILED", e);
196	        }
197	    }
198	
199	    /**
200	     * 배치 복호화.
201	     *
202	     * @param ciphertextList 암호화된 데이터 리스트
203	     * @return 복호화된 평문 리스트 또는 빈 리스트 (null/빈 입력 또는 실패 시)
204	     */
205	    public List<String> decryptBatch(List<String> ciphertextList) {
206	        if (ciphertextList == null || ciphertextList.isEmpty()) {
207	            return Collections.emptyList();
208	        }
209	        try {
210	            List<String> results = new ArrayList<>(ciphertextList.size());
211	            for (String ciphertext : ciphertextList) {
212	                results.add(decrypt(ciphertext));
213	            }
214	            return results;
215	        } catch (Exception e) {
216	            logger.error("AwsKmsEncryptionService - [decryptBatch] ERROR", e);
217	            throw new RuntimeException("ENCRYPTION_FAILED", e);
218	        }
219	    }
220	}
