import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.kms.KmsClient;

import java.net.URI;

/**
 * AWS Encryption SDK를 사용한 데이터 암복호화 서비스.
 * <p>
 * AWS Encryption SDK의 Envelope Encryption + Data Key Caching을 활용하여
 * KMS API 호출을 최소화하면서 안전한 암복호화를 수행한다.
 * <p>
 * {@link AwsKmsConfig}에서 CMK별 Bean으로 등록된다:
 * <ul>
 *   <li>"locationEncryptionService" — CMK 1: 위치/트래픽 (ECGI, GPS)</li>
 *   <li>"dataEncryptionService" — CMK 2: 개인정보 (CTN, IMEI 등)</li>
 * </ul>
 * <p>
 * SDK가 내부적으로 처리하는 항목:
 * <ul>
 *   <li>Data Key 생성 (GenerateDataKey)</li>
 *   <li>AES-GCM 암호화/복호화</li>
 *   <li>IV 생성 및 관리</li>
 *   <li>Envelope 바이너리 포맷 (encrypted message)</li>
 *   <li>Encryption Context 바인딩</li>
 * </ul>
 */
public class AwsKmsEncryptionService {

    private static final Logger logger = LoggerFactory.getLogger(AwsKmsEncryptionService.class);

    /** Data Key 캐시 최대 항목 수 */
    private static final int CACHE_CAPACITY = 100;
    /** 캐시된 Data Key 최대 유효 시간 (분) */
    private static final int MAX_AGE_MINUTES = 5;
    /** 하나의 캐시된 Data Key로 암호화할 수 있는 최대 메시지 수 */
    private static final int MAX_MESSAGES_PER_KEY = 1000000;

    private final AwsCrypto crypto;
    private final CachingCryptoMaterialsManager cachingCmm;
    private final MasterKeyProvider<KmsMasterKey> masterKeyProvider;

    public AwsKmsEncryptionService(String keyArn, String region) {
        // 1. AwsCrypto 인스턴스 (RequireEncryptRequireDecrypt = 기본 커밋 정책)
        this.crypto = AwsCrypto.builder()
                .withCommitmentPolicy(CommitmentPolicy.RequireEncryptRequireDecrypt)
                .build();

        // 2. KMS Master Key Provider (AWS SDK v2 기반)
        //    LocalStack 사용 시 endpoint override + dummy credential 설정
        KmsMasterKeyProvider.Builder providerBuilder = KmsMasterKeyProvider.builder()
                .defaultRegion(Region.of(region));

        String localstackEndpoint = System.getProperty("LOCALSTACK_ENDPOINT");
        KmsClient kmsClient;
        if (localstackEndpoint != null && !localstackEndpoint.isBlank()) {
            logger.info("AwsKmsEncryptionService: Using LocalStack endpoint = {}", localstackEndpoint);
            kmsClient = KmsClient.builder()
                    .region(Region.of(region))
                    .endpointOverride(URI.create(localstackEndpoint))
                    .credentialsProvider(StaticCredentialsProvider.create(
                            AwsBasicCredentials.create("test", "test")))
                    .build();
            providerBuilder.customRegionalClientSupplier(r -> kmsClient);
        } else {
            kmsClient = KmsClient.builder()
                    .region(Region.of(region))
                    .build();
        }

        // alias → ARN 변환 (환경 무관)
        // AWS Encryption SDK는 암호화 시 헤더에 항상 ARN을 기록하므로
        // buildStrict에도 ARN을 사용해야 복호화 시 key ID가 일치함
        if (keyArn.startsWith("alias/")) {
            String resolvedArn = kmsClient.describeKey(
                    software.amazon.awssdk.services.kms.model.DescribeKeyRequest.builder()
                            .keyId(keyArn).build()
            ).keyMetadata().arn();
            logger.info("AwsKmsEncryptionService: Resolved {} → {}", keyArn, resolvedArn);
            keyArn = resolvedArn;
        }

        this.masterKeyProvider = providerBuilder.buildStrict(keyArn);

        // 3. Data Key 캐싱 설정
        CryptoMaterialsCache cache = new LocalCryptoMaterialsCache(CACHE_CAPACITY);
        this.cachingCmm = CachingCryptoMaterialsManager.newBuilder()
                .withMasterKeyProvider(masterKeyProvider)
                .withCache(cache)
                .withMaxAge(MAX_AGE_MINUTES, TimeUnit.MINUTES)
                .withMessageUseLimit(MAX_MESSAGES_PER_KEY)
                .build();
    }

    /**
     * AWS Encryption SDK로 데이터 암호화.
     * <p>
     * SDK가 내부적으로 Data Key 생성, AES-GCM 암호화, Envelope 포맷 생성을 모두 처리한다.
     * CachingCMM을 통해 Data Key가 캐싱되어 KMS API 호출이 최소화된다.
     *
     * @param plaintext 평문 데이터
     * @return Base64 인코딩된 encrypted message 또는 빈 문자열 (null/빈 입력 또는 실패 시)
     */
    @SuppressWarnings("deprecation") // SDK 3.x: CachingCMM은 MasterKeyProvider만 지원, keyring 미지원
    public String encrypt(String plaintext) {
        if (plaintext == null || plaintext.isEmpty()) {
            return "";
        }
        try {
            long start = System.nanoTime();
            Map<String, String> encryptionContext = Collections.emptyMap();
            CryptoResult<byte[], ?> result = crypto.encryptData(
                    cachingCmm,
                    plaintext.getBytes(StandardCharsets.UTF_8),
                    encryptionContext);
            long elapsed = (System.nanoTime() - start) / 1_000_000;
            logger.info("[encrypt] completed in {}ms", elapsed);
            return Base64.getEncoder().encodeToString(result.getResult());
        } catch (Exception e) {
            logger.error("AwsKmsEncryptionService - [encrypt] ERROR", e);
            throw new RuntimeException("ENCRYPTION_FAILED", e);
        }
    }

    /**
     * AWS Encryption SDK로 데이터 복호화.
     *
     * @param ciphertext Base64 인코딩된 encrypted message
     * @return 복호화된 평문 또는 빈 문자열 (null/빈 입력 또는 실패 시)
     */
    @SuppressWarnings("deprecation") // SDK 3.x: strict mode MasterKeyProvider 사용
    public String decrypt(String ciphertext) {
        if (ciphertext == null || ciphertext.isEmpty()) {
            return "";
        }
        try {
            long start = System.nanoTime();
            byte[] encryptedBytes = Base64.getDecoder().decode(ciphertext);
            CryptoResult<byte[], ?> result = crypto.decryptData(
                    cachingCmm,
                    encryptedBytes);
            long elapsed = (System.nanoTime() - start) / 1_000_000;
            logger.info("[decrypt] completed in {}ms", elapsed);
            return new String(result.getResult(), StandardCharsets.UTF_8);
        } catch (Exception e) {
            logger.error("AwsKmsEncryptionService - [decrypt] ERROR", e);
            throw new RuntimeException("ENCRYPTION_FAILED", e);
        }
    }

    /**
     * 배치 암호화.
     * <p>
     * CachingCMM이 Data Key를 자동으로 캐싱하므로 배치 내에서
     * KMS API 호출이 최소화된다.
     *
     * @param plaintextList 평문 리스트
     * @return 암호화된 데이터 리스트 또는 빈 리스트 (null/빈 입력 또는 실패 시)
     */
    public List<String> encryptBatch(List<String> plaintextList) {
        if (plaintextList == null || plaintextList.isEmpty()) {
            return Collections.emptyList();
        }
        try {
            List<String> results = new ArrayList<>(plaintextList.size());
            for (String plaintext : plaintextList) {
                results.add(encrypt(plaintext));
            }
            return results;
        } catch (Exception e) {
            logger.error("AwsKmsEncryptionService - [encryptBatch] ERROR", e);
            throw new RuntimeException("ENCRYPTION_FAILED", e);
        }
    }

    /**
     * 배치 복호화.
     *
     * @param ciphertextList 암호화된 데이터 리스트
     * @return 복호화된 평문 리스트 또는 빈 리스트 (null/빈 입력 또는 실패 시)
     */
    public List<String> decryptBatch(List<String> ciphertextList) {
        if (ciphertextList == null || ciphertextList.isEmpty()) {
            return Collections.emptyList();
        }
        try {
            List<String> results = new ArrayList<>(ciphertextList.size());
            for (String ciphertext : ciphertextList) {
                results.add(decrypt(ciphertext));
            }
            return results;
        } catch (Exception e) {
            logger.error("AwsKmsEncryptionService - [decryptBatch] ERROR", e);
            throw new RuntimeException("ENCRYPTION_FAILED", e);
        }
    }
}

