package com.ahope.ds.blackbox;

import static com.ahope.ds.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.loginAdmin;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.testId;
import static com.ahope.ds.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.filter.cookie.CookieFilter;

/**
 * Black-Box API Integration Test (template-rendered)
 *
 * @target-controller QuotaController (src/main/java/com/ahope/ds/web/admin/quota/controller/QuotaController.java)
 * @target-api DELETE /web/admin/quotagroups
 *
 * 인증: AdminLoginInterceptor - AUTHZ='02' + CLIENT_ADDITIONAL_INFO.QUOTA_ONOFF='01' 필요(loginQuotaOnOff 세션값)
 * 요청: memberGroupSeqs[](query, long[], 필수) - 삭제 대상 그룹 시퀀스
 * 응답: ResultMap { err, removeCnt } - 대상 없으면 err=008(GROUP_NOT_FOUND)
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class QuotaGroupsDeleteBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "ACC", Long.toString(seq),
                "CLIENT", Long.toString(seq + 1),
                "GROUP", Long.toString(seq + 2),
                "ID", "bb" + testId(info));
    }

    private CookieFilter arrange(Map<String, String> p) {
        executeSqlTemplate("sql/quotagroups-teardown.sql", p);
        executeSqlTemplate("sql/quotagroups-setup.sql", p);
        return loginAdmin(p.get("ID"), "Test1234!", Long.parseLong(p.get("ACC")));
    }

    @Test
    void NTC_deleteGroup_removesExistingGroup(TestInfo info) {
        // 존재하는 그룹을 삭제하면 removeCnt=1, err=000
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .queryParam("memberGroupSeqs[]", p.get("GROUP"))
            .when()
                    .delete("/web/admin/quotagroups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("000"))
                    .body("removeCnt", equalTo(1));
        } finally {
            executeSqlTemplate("sql/quotagroups-teardown.sql", p);
        }
    }

    @Test
    void VTC_deleteGroup_nonExistentGroupReturnsGroupNotFound(TestInfo info) {
        // 존재하지 않는 그룹 시퀀스 -> affected=0 -> err=008
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .queryParam("memberGroupSeqs[]", "999999999")
            .when()
                    .delete("/web/admin/quotagroups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("008"));
        } finally {
            executeSqlTemplate("sql/quotagroups-teardown.sql", p);
        }
    }

    @Test
    void VTC_deleteGroup_missingGroupSeqsParamRejected(TestInfo info) {
        // 필수 query 파라미터 memberGroupSeqs[] 누락 -> 바인딩 실패 -> err=999
        Map<String, String> p = seed(info);
        CookieFilter cookies = arrange(p);
        try {
            given().filter(cookies).baseUri(BASE_URL)
                    .header("X-Requested-With", "XMLHttpRequest")
            .when()
                    .delete("/web/admin/quotagroups")
            .then()
                    .statusCode(200)
                    .body("err", equalTo("999"));
        } finally {
            executeSqlTemplate("sql/quotagroups-teardown.sql", p);
        }
    }
}

